mapper.insert:
INSERT INTO good_places (
	user_id,
	group_id,
	place_id
)
VALUES (
	#{userId},
	#{groupId},
	#{placeId}
)

mapper.select:
SELECT
	id,
	user_id,
	group_id,
	place_id,
	created_at
FROM good_places
WHERE user_id = #{userId}
  AND group_id = #{groupId}
  AND place_id = #{placeId}

mapper.delete:
DELETE FROM good_places
WHERE user_id = #{userId}
  AND group_id = #{groupId}
  AND place_id = #{placeId}
